<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CBT Result</title><style>body{font-family:Arial;background:#f2f5f7;color:#17212b}.wrap{max-width:760px;margin:40px auto;background:#fff;padding:28px;border-radius:14px;border:1px solid #dce3ea}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:#eef3f6;padding:16px;border-radius:10px}.muted{color:#68798a}</style></head><body><main class="wrap"><p class="muted">TAGORE VEDANT ACADEMY · CBT RESULT</p><h1>{{ $attempt->paper_name }}</h1><p><strong>{{ $attempt->exam_type }}</strong> · Attempt {{ $attempt->attempt_no }} · {{ ucfirst($attempt->status) }}</p><div class="stats"><div class="stat"><small>Score</small><h2>{{ number_format((float)$attempt->score,2) }} / {{ number_format((float)$attempt->max_score,2) }}</h2></div><div class="stat"><small>Rank</small><h2>{{ $attempt->rank ?? '—' }}</h2></div><div class="stat"><small>Percentile</small><h2>{{ $attempt->percentile===null?'—':number_format((float)$attempt->percentile,2).'%' }}</h2></div></div><p>Correct: {{ $attempt->correct_count }} · Incorrect: {{ $attempt->incorrect_count }} · Unanswered: {{ $attempt->unanswered_count }}</p><a href="{{ route('tagore.cbt.index') }}">Back to CBT</a></main></body></html>